  return [...ids].filter((k) => st[k] || PRODUCTS()[k]).map((k) => ({ k, it: st[k] || { ...PRODUCTS()[k], left: 0 }, low: st[k] ? isLow(st[k]) : true, manual: !!man[k] }))
